?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nhập kết quả · Hội thao Agribank 2026</title><style>
:root{--g:#087849;--gd:#075b3b;--ink:#173b2d;--line:#dbe5df;--bg:#f3f7f4}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:16px Arial,sans-serif;color:var(--ink)}header{background:linear-gradient(120deg,var(--gd),var(--g));color:white;padding:22px max(16px,calc((100vw - 1200px)/2));border-bottom:5px solid #e5c36b}header h1{margin:0;font-size:clamp(24px,4vw,34px)}header p{margin:6px 0 0;color:#e4f3e9}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.actions a,.actions button{border:1px solid #ffffff70;background:#ffffff15;color:white;text-decoration:none;border-radius:8px;padding:9px 12px;font-weight:bold;cursor:pointer}main{max-width:1200px;margin:22px auto;padding:0 14px}.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:16px;margin-bottom:16px}.filters{display:grid;grid-template-columns:1fr 1fr;gap:10px}.filters input,.filters select{width:100%;min-height:43px;padding:9px;border:1px solid #cad9d0;border-radius:8px;font-size:16px}.stats{margin:12px 0;color:#5d7066}.match{display:grid;grid-template-columns:minmax(0,1fr) 130px 150px 110px;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid var(--line)}.match:last-child{border-bottom:0}.match strong{display:block;color:var(--gd)}.muted{font-size:13px;color:#6b7d73;margin-top:4px}.match input,.match select{width:100%;min-height:40px;border:1px solid #cbd9d0;border-radius:8px;padding:8px;font-size:15px}.save{background:var(--g);color:white;border:0;border-radius:8px;padding:10px;font-weight:bold;cursor:pointer}.save:disabled{opacity:.55}.message{padding:10px;border-radius:8px;background:#e8f5ed;margin:10px 0;display:none}.help{background:#fff7df;border-left:4px solid #d7a43b;padding:12px;border-radius:8px;margin-top:12px}.badge{font-size:12px;border-radius:20px;background:#e8f5ed;padding:4px 8px}@media(max-width:800px){.match{grid-template-columns:1fr 1fr}.match .fixture{grid-column:1/-1}.filters{grid-template-columns:1fr}}@media(max-width:460px){.match{grid-template-columns:1fr}.match .fixture{grid-column:auto}}</style></head><body><header><h1>Nhập và cập nhật kết quả thi đấu</h1><p>Hội thao Agribank lần thứ X · Khu vực Miền núi và Trung du Bắc Bộ · Năm 2026</p><div class="actions"><a href="../dia-diem-lich-thi-dau.html" target="_blank">Xem lịch công khai ↗</a><a href="logout.php">Đăng xuất</a></div></header><main><section class="panel"><div class="filters"><select id="sport"><option value="">Tất cả môn</option><option value="football">Bóng đá mini nam</option><option value="volley">Bóng chuyền hơi nữ</option><option value="pickle">Pickleball</option></select><input id="search" placeholder="Tìm đội/chi nhánh, mã trận, ngày…"></div><div id="stats" class="stats">Đang tải danh sách trận…</div><div id="message" class="message" role="status"></div><div class="help"><strong>Cách nhập:</strong> Bóng đá nhập dạng <b>2-1</b>; bóng chuyền có thể nhập <b>2-0 (21-15, 21-18)</b>; Pickleball nhập <b>11-7, 11-9</b>. Trạng thái “Đang thi đấu” hoặc “Kết thúc” sẽ được hiển thị ở trang lịch công khai. Để xóa kết quả đã nhập, để trống tỷ số, chọn “Chưa cập nhật” rồi bấm Lưu.</div></section><section class="panel"><div id="matches"></div></section></main><script src="../assets/matches.js"></script><script>
const datasets={football:window.HOI_THAO_MATCHES.football,volley:window.HOI_THAO_MATCHES.volley,pickle:window.HOI_THAO_MATCHES.pickle};
const names={football:'Bóng đá mini nam',volley:'Bóng chuyền hơi nữ',pickle:'Pickleball'};
let saved={};
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fixture(sport,row,i){let date=row[0],teams=sport==='football'?row[4]:sport==='volley'?row[4]:row[6],meta=sport==='football'?'Giờ '+row[1]+' · Sân '+row[5]+' · Bảng/vòng '+row[3]:sport==='volley'?'Buổi '+row[1]+' · '+row[5]+' · Bảng/vòng '+row[3]:'Buổi '+row[1]+' · '+row[2]+' · '+row[4]+' · Bảng/vòng '+row[5];return {key:sport+'-'+i,sport,row,date,teams,meta,idx:i}}
function allFixtures(){return Object.keys(datasets).flatMap(s=>datasets[s].map((r,i)=>fixture(s,r,i)))}
function render(){const sport=document.getElementById('sport').value,q=document.getElementById('search').value.trim().toLocaleLowerCase('vi');const all=allFixtures().filter(f=>(!sport||f.sport===sport)&&(!q||[f.key,names[f.sport],f.date,f.teams,f.meta].join(' ').toLocaleLowerCase('vi').includes(q)));document.getElementById('stats').textContent='Hiển thị '+all.length+' trận · Đã có kết quả '+all.filter(f=>saved[f.key]&&saved[f.key].score).length+' trận';document.getElementById('matches').innerHTML=all.map(f=>{const r=saved[f.key]||{};return '<div class="match"><div class="fixture"><strong>'+esc(names[f.sport])+' · '+esc(f.key)+'</strong><div>'+esc(f.teams)+'</div><div class="muted">'+esc(f.date+' · '+f.meta)+'</div></div><input aria-label="Tỷ số '+esc(f.key)+'" data-score="'+esc(f.key)+'" value="'+esc(r.score||'')+'" placeholder="Nhập tỷ số"><select aria-label="Trạng thái '+esc(f.key)+'" data-status="'+esc(f.key)+'"><option value="pending" '+((r.status||'pending')==='pending'?'selected':'')+'>Chưa cập nhật</option><option value="live" '+(r.status==='live'?'selected':'')+'>Đang thi đấu</option><option value="finished" '+(r.status==='finished'?'selected':'')+'>Kết thúc</option></select><button class="save" data-save="'+esc(f.key)+'">Lưu</button></div>'}).join('')||'<p>Không có trận phù hợp.</p>';document.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',()=>save(b.dataset.save)))}
async function load(){try{const r=await fetch('../api/results.php',{cache:'no-store'});const j=await r.json();if(j.ok)saved=j.results||{};}catch(e){}render()}
async function save(key){const f=allFixtures().find(x=>x.key===key);if(!f)return;const btn=document.querySelector('[data-save="'+key+'"]');btn.disabled=true;const payload={fixture_key:key,sport:f.sport,score:document.querySelector('[data-score="'+key+'"]').value.trim(),status:document.querySelector('[data-status="'+key+'"]').value};try{const r=await fetch('../api/save-result.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'Lỗi lưu');const msg=document.getElementById('message');msg.textContent=j.message+' ('+key+')';msg.style.display='block';await load()}catch(e){const msg=document.getElementById('message');msg.textContent='Không lưu được: '+e.message+' · Kiểm tra config.php và bảng dữ liệu.';msg.style.display='block'}finally{btn.disabled=false}}
document.getElementById('sport').addEventListener('change',render);document.getElementById('search').addEventListener('input',render);load();
</script></body></html>
